import React, { useState } from 'react';
import { ConfirmDialog } from 'primereact/confirmdialog';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="confirmDialog-accessibility">Accessible ConfirmDialog</label>
            <ConfirmDialog 
                id="confirmDialog-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible ConfirmDialog input"
                placeholder="Enter confirmDialog"
            />
        </div>
    );
}